namespace LibraryApp.Domain.Common;

/// <summary>
/// Base type of every entity that has its own identifier (SD-01: <see cref="Guid"/>, generated by the application).
/// Tables that are pure links (for example <c>BookAuthor</c> with a composite key) do not inherit it.
/// </summary>
public abstract class Entity
{
    protected Entity() { }

    protected Entity(Guid id)
    {
        if (id == Guid.Empty)
            throw new ArgumentException("An entity identifier must not be empty.", nameof(id));

        Id = id;
    }

    public Guid Id { get; private set; }
}
